import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 15
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    first_nonblank = None
    first_expected_width = None
    header_index = None
    label_pattern = re.compile(r"[^\W\d_][\w\s./()%-]*")

    for index, record in enumerate(records):
        if not record or (len(record) == 1 and not record[0].strip()):
            continue
        if first_nonblank is None:
            first_nonblank = index
        if len(record) != expected_width:
            continue
        if first_expected_width is None:
            first_expected_width = index
        if all(label_pattern.fullmatch(value.strip()) for value in record):
            header_index = index
            break

    if header_index is None:
        header_index = first_expected_width
    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Keep surplus fields in extra columns rather than truncating them.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
